mapper.select:
select (doc->'settings'->'tutor')::text tu, (doc->'org'->'room')::text room, doc->'org'->>'type' type, (doc->'lsite'->'pub')::text pub,
       (doc->'members')::text members, (doc->'classes')::text classes, (doc->'badges')::text badges, (doc->'tq')::text tq, (doc->'bkgrades')::text bkgrades
  from tenant_state where tenant_id = #{tid}
